#!/bin/bash
# Configuration
PASS="th1s1s3up34e5r37"

# RED Cluster Info
RED_IP="172.27.3.23"
RED_DNS="nifi-red.inspire-silrelease.svc.cluster.local"
RED_DNS2="nifi-red-0.nifi-red-headless.inspire-silrelease.svc.cluster.local"

# BLACK Cluster Info
BLACK_IP="172.27.3.12"
BLACK_DNS="nifi-black.inspire-silrelease.svc.cluster.local"
BLACK_DNS2="nifi-black-0.nifi-black-headless.inspire-silrelease.svc.cluster.local"

echo "1. Generating Shared Root CA (The Trust Source)..."
openssl req -new -x509 -keyout root-ca.key -out root-ca.crt -days 3650 -nodes -subj "/CN=NiFi-Shared-Root-CA"

generate_nifi_p12() {
    local NAME=$1
    local IP=$2
    local DNS=$3
    local DNS2=$4

    echo "Creating PKCS12 for $NAME ($DNS)..."

    # Create OpenSSL config to force SAN (IP and DNS)
    cat > "${NAME}-san.conf" <<EOF
[req]
distinguished_name = req_distinguished_name
req_extensions = v3_req
prompt = no
[req_distinguished_name]
CN = ${DNS}
[v3_req]
subjectAltName = IP:${IP},DNS:${DNS},DNS:${DNS2}
keyUsage = digitalSignature, keyEncipherment
extendedKeyUsage = serverAuth, clientAuth
EOF

    # Generate Private Key and CSR
    openssl req -new -nodes -keyout "${NAME}.key" -out "${NAME}.csr" -config "${NAME}-san.conf"

    # Sign with Shared Root CA
    openssl x509 -req -in "${NAME}.csr" -CA root-ca.crt -CAkey root-ca.key -CAcreateserial \
        -out "${NAME}.crt" -days 825 -extensions v3_req -extfile "${NAME}-san.conf"

    # Create Keystore (PKCS12)
    openssl pkcs12 -export -in "${NAME}.crt" -inkey "${NAME}.key" -certfile root-ca.crt \
        -out "${NAME}-keystore.p12" -name "nifi-key" -passout "pass:${PASS}"

    # Create Truststore (PKCS12) - contains the Shared Root CA
    keytool -importcert -alias "nifi-root" -file root-ca.crt -keystore "${NAME}-truststore.p12" \
        -storetype PKCS12 -storepass "${PASS}" -noprompt
}

generate_nifi_p12 "red" "$RED_IP" "$RED_DNS" "$RED_DNS2"
generate_nifi_p12 "black" "$BLACK_IP" "$BLACK_DNS" "$BLACK_DNS2"

echo "------------------------------------------------"
echo "DONE! Your files are ready:"
echo "RED: red-keystore.p12, red-truststore.p12"
echo "BLACK: black-keystore.p12, black-truststore.p12"


## Black Keystore String
cat black-keystore.p12 | base64 | tr -d '\n'


#
## Black Truststore String
cat black-truststore.p12 | base64 | tr -d '\n'


#
#
## Red Keystore String
cat red-keystore.p12 | base64 | tr -d '\n'


#
## Red Truststore String
cat red-truststore.p12 | base64 | tr -d '\n'





